import React, { useState } from "react";
import api from "../services/api";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

export interface Attendee {
  name: string;
  email: string;
}

interface CreateEventFormProps {
  onCreated?: () => void;
}

export default function CreateEventForm({ onCreated }: CreateEventFormProps) {
  const [name, setName] = useState("");
  const [venue, setVenue] = useState("");
  const [start, setStart] = useState<Date | null>(null);
  const [end, setEnd] = useState<Date | null>(null);
  const [attendees, setAttendees] = useState<Attendee[]>([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const addAttendee = () => setAttendees(prev => [...prev, { name: "", email: "" }]);
  const updateAttendee = (i: number, field: keyof Attendee, value: string) =>
    setAttendees(prev => prev.map((a, idx) => (idx === i ? { ...a, [field]: value } : a)));

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!start || !end) return setError("Please select start and end date/time");

    setLoading(true);
    setError(null);
    setMessage(null);

    try {
      await api.post("/api/Events", {
        name,
        venue,
        startTime: start.toISOString(),
        endTime: end.toISOString(),
        attendees,
      });

      setMessage("✅ Event created successfully!");
      setName(""); setVenue(""); setStart(null); setEnd(null); setAttendees([]);
      onCreated?.();
    } catch (err: any) {
      console.error(err);
      setError(err?.message || "Failed to create event.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      maxWidth: "650px",
      margin: "2rem auto",
      padding: "2rem",
      borderRadius: "10px",
      border: "1px solid #ddd",
      boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
      backgroundColor: "#f9f9f9",
      fontFamily: "Arial, sans-serif"
    }}>
      <h2 style={{ textAlign: "center", marginBottom: "1.5rem" }}>➕ Create Event</h2>

      {message && <p style={{ color: "green", textAlign: "center" }}>{message}</p>}
      {error && <p style={{ color: "red", textAlign: "center" }}>{error}</p>}

      <form onSubmit={submit} style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
        <input
          placeholder="Event Name"
          value={name}
          onChange={e => setName(e.target.value)}
          required
          style={{ padding: "0.75rem", borderRadius: "6px", border: "1px solid #ccc" }}
        />

        {/* DatePickers wrapped in divs for styling */}
        <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap" }}>
          <div style={{ flex: 1 }}>
            <label>Start Date & Time</label>
            <DatePicker
              selected={start}
              onChange={(date: Date | null) => date && setStart(date)}
              showTimeSelect
              timeFormat="HH:mm"
              timeIntervals={15}
              dateFormat="yyyy-MM-dd HH:mm"
              placeholderText="Select start date & time"
              required
              className="datepicker-input"
            />
          </div>

          <div style={{ flex: 1 }}>
            <label>End Date & Time</label>
            <DatePicker
              selected={end}
              onChange={(date: Date | null) => date && setEnd(date)}
              showTimeSelect
              timeFormat="HH:mm"
              timeIntervals={15}
              dateFormat="yyyy-MM-dd HH:mm"
              placeholderText="Select end date & time"
              required
              className="datepicker-input"
            />
          </div>
        </div>

        <input
          placeholder="Venue"
          value={venue}
          onChange={e => setVenue(e.target.value)}
          required
          style={{ padding: "0.75rem", borderRadius: "6px", border: "1px solid #ccc" }}
        />

        <div>
          <h3>Attendees</h3>
          {attendees.map((a, i) => (
            <div key={i} style={{ display: "flex", gap: "0.5rem", flexWrap: "wrap", marginBottom: "0.5rem" }}>
              <input
                placeholder="Name"
                value={a.name}
                onChange={e => updateAttendee(i, "name", e.target.value)}
                required
                style={{ flex: 1, padding: "0.5rem", borderRadius: "4px", border: "1px solid #ccc" }}
              />
              <input
                placeholder="Email"
                type="email"
                value={a.email}
                onChange={e => updateAttendee(i, "email", e.target.value)}
                required
                style={{ flex: 1, padding: "0.5rem", borderRadius: "4px", border: "1px solid #ccc" }}
              />
            </div>
          ))}
          <button
            type="button"
            onClick={addAttendee}
            style={{ padding: "0.5rem 1rem", borderRadius: "6px", border: "none", backgroundColor: "#28a745", color: "#fff", cursor: "pointer" }}
          >
            + Add Attendee
          </button>
        </div>

        <button
          type="submit"
          disabled={loading}
          style={{
            marginTop: "1rem",
            padding: "0.75rem",
            borderRadius: "6px",
            border: "none",
            backgroundColor: "#007bff",
            color: "#fff",
            fontSize: "1rem",
            cursor: loading ? "not-allowed" : "pointer"
          }}
        >
          {loading ? "Creating..." : "Create Event"}
        </button>
      </form>
    </div>
  );
}
